  final String externalInvoiceNumber;
  final String normalizedExternalInvoiceNumber;
  final int invoiceDateMs;
  final String locationId;
  final String status;
  final int subtotalPaise;
  final int landedCostTotalPaise;
  final int totalTaxPaise;
  final int netTotalPaise;
  final int amountPaidPaise;
  final int balanceDuePaise;
  final int createdAtUtcMs;
  final String? paymentTerms;
  final String? notes;
  const PurchaseHeaderRow({
    required this.id,
    required this.organizationId,
    required this.branchId,
    required this.documentHeaderId,
    required this.supplierId,
    required this.supplierName,
    required this.externalInvoiceNumber,
    required this.normalizedExternalInvoiceNumber,
    required this.invoiceDateMs,
    required this.locationId,
    required this.status,
    required this.subtotalPaise,
