    map['document_header_id'] = Variable<String>(documentHeaderId);
    map['supplier_id'] = Variable<String>(supplierId);
    map['supplier_name'] = Variable<String>(supplierName);
    map['external_invoice_number'] = Variable<String>(externalInvoiceNumber);
    map['normalized_external_invoice_number'] = Variable<String>(
      normalizedExternalInvoiceNumber,
    );
