    return PurchaseHeadersCompanion(
      id: Value(id),
      organizationId: Value(organizationId),
      branchId: Value(branchId),
      documentHeaderId: Value(documentHeaderId),
      supplierId: Value(supplierId),
      supplierName: Value(supplierName),
      externalInvoiceNumber: Value(externalInvoiceNumber),
      normalizedExternalInvoiceNumber: Value(normalizedExternalInvoiceNumber),
      invoiceDateMs: Value(invoiceDateMs),
      locationId: Value(locationId),
      status: Value(status),
      subtotalPaise: Value(subtotalPaise),
      landedCostTotalPaise: Value(landedCostTotalPaise),
      totalTaxPaise: Value(totalTaxPaise),
      netTotalPaise: Value(netTotalPaise),
      amountPaidPaise: Value(amountPaidPaise),
      balanceDuePaise: Value(balanceDuePaise),
      createdAtUtcMs: Value(createdAtUtcMs),
      paymentTerms: paymentTerms == null && nullToAbsent
          ? const Value.absent()
          : Value(paymentTerms),
      notes: notes == null && nullToAbsent
